    'equipe_titre' => ['fr' => 'Notre Équipe', 'en' => 'Our Team', 'mg' => 'Ny Ekipantsika'],
    'equipe_soustitre' => ['fr' => 'Les étudiants qui ont conçu et développé ce site.', 'en' => 'The students who designed and developed this site.', 'mg' => 'Ireo mpianatra namolavola sy nanamboatra ity tranonkala ity.'],
    'equipe_intro' => ['fr' => "Derrière chaque page, chaque animation et chaque ligne de code de ce site se cache le travail d'une petite équipe d'étudiants en Génie Informatique, en Licence 3 à l'ISSTM. Ce projet est le fruit de leur travail collectif, mené avec passion dans le cadre de leur formation.", 'en' => 'Behind each page, each animation and each line of code on this site hides the work of a small team of Computer Engineering students, in License 3 at ISSTM. This project is the fruit of their collective work, carried out with passion as part of their training.', 'mg' => "Ao ambadiky ny pejy tsirairay, ny sary mihetsika tsirairay ary ny andalan-tsoratra tsirairay amin'ity tranonkala ity dia miafina ny asan'ny ekipa kelin'ny mpianatra Injeniera Informatika, ao amin'ny Licence 3 ao amin'ny ISSTM. Ity tetikasa ity dia vokatry ny fiaraha-miasan'izy ireo, notanterahina tamim-pitiavana tao anatin'ny fiofanany."],
    'equipe_mention_m' => ['fr' => 'Étudiant en Génie Informatique — ISSTM', 'en' => 'Student in Computer Engineering — ISSTM', 'mg' => 'Mpianatra amin\'ny Injeniera Informatika — ISSTM'],
    'equipe_mention_f' => ['fr' => 'Étudiante en Génie Informatique — ISSTM', 'en' => 'Student in Computer Engineering — ISSTM', 'mg' => 'Mpianatravavy amin\'ny Injeniera Informatika — ISSTM'],
    'equipe_role_mirindra' => ['fr' => 'Leader & Développeur Frontend', 'en' => 'Frontend Leader & Developer', 'mg' => 'Mpitarika & Mpamorona Frontend'],
    'equipe_badge_leader' => ['fr' => 'À l\'honneur', 'en' => 'In the spotlight', 'mg' => 'Eo amin\'ny lampihazo'],
    'equipe_bio_mirindra' => ['fr' => "Leader et développeur Frontend, Mirindra a mis sa passion pour l'expérience utilisateur au service de ce site : conception des interfaces, animations et attention portée à chaque détail visuel, du header jusqu'à la dernière page. Toujours curieux et à l'aise avec de nouveaux outils, il s'est aussi chargé de l'organisation et de la planification du travail d'équipe, pour avancer ensemble vers une expérience fluide, moderne et cohérente.", 'en' => "Leader and Frontend developer, Mirindra has put his passion for user experience at the service of this site: interface design, animations and attention to every visual detail, from the header to the last page. Always curious and comfortable with new tools, he was also responsible for organizing and planning teamwork, to move forward together towards a fluid, modern and coherent experience.", 'mg' => "Mpitarika sy mpamorona Frontend, Mirindra dia nametraka ny fitiavany ny traikefan'ny mpampiasa amin'ny serivisy amin'ity tranokala ity : famolavolana interface tsara, sary mihetsika ary fifantohana amin'ny antsipiriany rehetra hita maso, manomboka amin'ny lohapejy ka hatramin'ny pejy farany. Te hahafanta-javatra foana sy mahazo aina amin'ny fitaovana vaovao, izy ihany koa no tompon'andraikitra amin'ny fandaminana sy ny fanomanana ny fiaraha-miasan'ny ekipa, mba hiara-mandroso mankany amin'ny traikefa mafana sy maoderina ary mirindra."],
    'equipe_highlight_mirindra' => ['fr' => "Un développeur passionné, minutieux et engagé, du premier croquis jusqu'à la mise en ligne du site.", 'en' => 'A passionate, meticulous and committed developer, from the first sketch to putting the site online.', 'mg' => "Mpamorona mafana fo, mazoto ary manolo-tena, manomboka amin'ny sketch voalohany ka hatramin'ny fametrahana ny tranokala an-tserasera."],
    'equipe_role_safidy' => ['fr' => 'Développeur Backend', 'en' => 'Backend Developer', 'mg' => 'Mpamorona Backend'],
    'equipe_bio_safidy' => ['fr' => "Architecte de l'ombre, Safidy a bâti les fondations solides sur lesquelles repose tout le site : bases de données, logique métier et sécurité des échanges. Rigoureux et méthodique, il a conçu un backend robuste capable d'accompagner la croissance de l'ISSTM sans jamais faillir. Son travail, invisible pour le visiteur, est pourtant le socle sur lequel tout le reste a pu être construit.", 'en' => 'A behind-the-scenes architect, Safidy built the solid foundations on which the whole site rests: databases, business logic and the security of every exchange. Rigorous and methodical, he designed a robust backend able to support ISSTM\'s growth without ever failing. His work, invisible to visitors, is nonetheless the base on which everything else could be built.', 'mg' => "Mpanamboatra alokaloka, i Safidy no nanorina ny fototra matanjaka iorenan'ny tranonkala manontolo: angon-drakitra, lojika ara-draharaha ary fiarovana ny fifanakalozana. Hentitra sy mirindra, namolavola backend matanjaka afaka manohana ny fitomboan'ny ISSTM izy, tsy misy tsininy. Ny asany, tsy hitan'ny mpitsidika, no fototra niorenan'ny zava-drehetra hafa."],
    'equipe_role_jameelah' => ['fr' => 'Assistante Frontend', 'en' => 'Frontend Assistant', 'mg' => 'Mpanampy Frontend'],
    'equipe_bio_jameelah' => ['fr' => "Œil attentif aux détails, Jameelah a épaulé le développement de l'interface avec créativité et précision. Entre ajustements visuels, tests d'ergonomie et petites touches qui font toute la différence, elle a contribué à peaufiner l'expérience offerte à chaque visiteur du site. Son sens du détail a permis de transformer de bonnes idées en une interface réellement agréable à utiliser.", 'en' => "With a keen eye for detail, Jameelah supported the development of the interface with creativity and precision. Between visual adjustments, usability tests and the small touches that make all the difference, she helped refine the experience offered to every visitor of the site. Her attention to detail turned good ideas into an interface that is genuinely pleasant to use.", 'mg' => "Manana maso maranitra amin'ny antsipiriany, i Jameelah no nanohana ny fampivelarana ny sehatra fifandraisana tamin'ny fahaiza-mamorona sy ny fahamarinana. Eo anelanelan'ny fanitsiana hita maso, ny fitsapana fampiasana ary ireo fikasihana kely mampiavaka, dia nandray anjara tamin'ny fanatsarana ny traikefa omena ny mpitsidika tsirairay. Ny fahamalinany tamin'ny antsipiriany no nahafahana nanova hevitra tsara ho sehatra tena mahafinaritra ampiasaina."],
    'equipe_role_tanael' => ['fr' => 'Assistant Backend', 'en' => 'Backend Assistant', 'mg' => 'Mpanampy Backend'],
    'equipe_bio_tanael' => ['fr' => "Complice de l'ombre côté serveur, Tanael a prêté main forte à la construction de la logique backend et à la fiabilité des données. Curieux et impliqué, il a participé aux tests, aux corrections et à l'optimisation des performances du site. Son soutien a été précieux pour livrer un backend à la fois stable et évolutif.", 'en' => "A quiet accomplice on the server side, Tanael lent a hand in building the backend logic and ensuring data reliability. Curious and involved, he took part in testing, fixes and performance optimization of the site. His support was invaluable in delivering a backend that is both stable and scalable.", 'mg' => "Namana miafina eo amin'ny lafiny mpizara, i Tanael no nanome tanana tamin'ny fananganana ny lojika backend sy ny fahatokisan'ny angon-drakitra. Liana sy nandray anjara, nandray anjara tamin'ny fitsapana, ny fanitsiana ary ny fanatsarana ny fahombiazan'ny tranonkala izy. Sarobidy ny fanohanany tamin'ny fanaterana backend matanjaka sady mety hitombo."],
    'equipe_merci' => ['fr' => 'Merci d\'avoir visité notre site, conçu avec passion par notre équipe.', 'en' => 'Thank you for visiting our site, designed with passion by our team.', 'mg' => 'Misaotra anao nitsidika ny tranonkalanay, novolavolain\'ny ekipanay tamim-pitiavana.'],
    'erreur_404_titre' => ['fr' => 'Page introuvable', 'en' => 'Page not found', 'mg' => 'Tsy hita ny pejy'],
    'erreur_404_code' => ['fr' => 'Erreur 404', 'en' => 'Error 404', 'mg' => 'Fahadisoana 404'],
    'erreur_404_texte' => ['fr' => 'Désolé, la page que vous recherchez n\'existe pas ou a été déplacée.', 'en' => 'Sorry, the page you are looking for does not exist or has been moved.', 'mg' => 'Miala tsiny, tsy misy na efa nafindra ny pejy tadiavinao.'],
    'erreur_404_retour_accueil' => ['fr' => 'Retour à l\'accueil', 'en' => 'Back to homepage', 'mg' => 'Miverina any amin\'ny pejy fanombohana'],
    'erreur_404_recherche' => ['fr' => 'Ou lancez une recherche sur le site', 'en' => 'Or search the site', 'mg' => 'Na mikaroka eto amin\'ny tranonkala'],
    'footer_mentions_legales' => ['fr' => 'Mentions légales', 'en' => 'Legal Notice', 'mg' => 'Fanambarana ara-dalàna'],
    'filieres_filtre_niveau' => ['fr' => 'Filtrer par niveau', 'en' => 'Filter by level', 'mg' => 'Sivano araka ny ambaratonga'],
    'filieres_filtre_mention' => ['fr' => 'Filtrer par mention', 'en' => 'Filter by major', 'mg' => 'Sivano araka ny mention'],
