    // --- Page Politique de confidentialité ---
    'confidentialite_titre' => ['fr' => 'Politique de confidentialité', 'en' => 'Privacy Policy', 'mg' => 'Politikan\'ny fiainana tsiambaratelo'],
    'confidentialite_soustitre' => ['fr' => 'Comment l\'ISSTM Mahajanga collecte, utilise et protège vos données personnelles.', 'en' => 'How ISSTM Mahajanga collects, uses and protects your personal data.', 'mg' => 'Ny fomba fitantanan\'ny ISSTM Mahajanga ny angona manokanao.'],
    'confidentialite_maj' => ['fr' => 'Dernière mise à jour', 'en' => 'Last updated', 'mg' => 'Nohavaozina farany'],
    'confidentialite_s1_titre' => ['fr' => '1. Données collectées', 'en' => '1. Data we collect', 'mg' => '1. Angona angonina'],
    'confidentialite_s1_texte' => ['fr' => 'Dans le cadre de l\'utilisation de ce site (inscription en ligne, création de compte, formulaire de contact, newsletter), nous pouvons collecter : votre nom, prénom, adresse email, numéro de téléphone, ainsi que les informations que vous saisissez volontairement dans nos formulaires.', 'en' => 'When you use this site (online registration, account creation, contact form, newsletter), we may collect: your name, email address, phone number, and any information you voluntarily enter in our forms.', 'mg' => 'Amin\'ny fampiasana ity tranonkala ity (fisoratana anarana an-tserasera, famoronana kaonty, taratasy fifandraisana, taratasy vaovao), afaka mangoina izahay ny anaranao, adiresy mailaka, laharana finday, ary ny fampahalalana ampidirinao an-tsitrapo ao amin\'ny endrikasika.'],
    'confidentialite_s2_titre' => ['fr' => '2. Utilisation des données', 'en' => '2. How we use your data', 'mg' => '2. Fampiasana ny angona'],
    'confidentialite_s2_texte' => ['fr' => 'Ces données sont utilisées exclusivement pour le traitement des inscriptions et candidatures, la gestion de votre compte, la réponse à vos demandes de contact, et l\'envoi de la newsletter si vous y êtes abonné(e). Elles ne sont jamais vendues ni cédées à des tiers à des fins commerciales.', 'en' => 'This data is used exclusively to process registrations and applications, manage your account, respond to your contact requests, and send the newsletter if you are subscribed. It is never sold or transferred to third parties for commercial purposes.', 'mg' => 'Ampiasaina hanatanterahana ny fisoratana anarana sy ny fangatahana, hitantanana ny kaontinao, hamaliana ny fangatahanao, ary handefasana ny taratasy vaovao raha manao fisoratana anarana ianao ireo angona ireo. Tsy amidy na omena olon-kafa ho an\'ny tombontsoa ara-barotra mihitsy izy ireo.'],
    'confidentialite_s3_titre' => ['fr' => '3. Cookies et session', 'en' => '3. Cookies and session', 'mg' => '3. Cookies sy session'],
    'confidentialite_s3_texte' => ['fr' => 'Le site utilise des cookies de session strictement nécessaires à son fonctionnement (maintien de la connexion, préférence de langue, thème visuel, comptage d\'une visite par session). Aucun cookie publicitaire ou de traçage tiers n\'est utilisé.', 'en' => 'The site uses session cookies strictly necessary for its operation (login persistence, language preference, visual theme, one visit counted per session). No advertising or third-party tracking cookies are used.', 'mg' => 'Mampiasa cookies session ilaina tokoa amin\'ny fandehanan\'ny tranonkala ny tranonkala (fitanana ny fidirana, safidim-piteny, endrika, fanisana tsidihana iray isaky ny session). Tsy misy cookies dokambarotra na fanaraha-maso avy amin\'olon-kafa ampiasaina.'],
    'confidentialite_s4_titre' => ['fr' => '4. Sécurité et conservation', 'en' => '4. Security and retention', 'mg' => '4. Fiarovana sy fitehirizana'],
    'confidentialite_s4_texte' => ['fr' => 'Les mots de passe sont stockés de façon chiffrée et l\'accès aux données personnelles est restreint au personnel administratif habilité de l\'ISSTM. Les données sont conservées le temps nécessaire à la finalité pour laquelle elles ont été collectées.', 'en' => 'Passwords are stored encrypted and access to personal data is restricted to authorized ISSTM administrative staff. Data is kept only as long as necessary for the purpose it was collected for.', 'mg' => 'Voatahiry am-panafenana ny tenimiafina ary voafetra amin\'ny mpiasa ara-pitantanana voatendrin\'ny ISSTM ihany ny fidirana amin\'ny angona manokana. Tehirizina araka izay ilaina ho an\'ny tanjona nangonana azy ireo angona.'],
    'confidentialite_s5_titre' => ['fr' => '5. Vos droits', 'en' => '5. Your rights', 'mg' => '5. Ny zonao'],
    'confidentialite_s5_texte' => ['fr' => 'Vous pouvez à tout moment demander l\'accès, la correction ou la suppression de vos données personnelles en nous contactant à isstm.univ.umg@gmail.com.', 'en' => 'You may at any time request access to, correction of, or deletion of your personal data by contacting us at isstm.univ.umg@gmail.com.', 'mg' => 'Afaka mangataka ny fidirana, ny fanitsiana na ny famafana ny angona manokanao amin\'ny alalan\'ny fifandraisana aminay amin\'ny isstm.univ.umg@gmail.com ianao amin\'ny fotoana rehetra.'],

    // --- Page Mentions légales ---
    'mentions_legales_titre' => ['fr' => 'Mentions légales', 'en' => 'Legal Notice', 'mg' => 'Fanambarana ara-dalàna'],
    'mentions_legales_soustitre' => ['fr' => 'Informations légales relatives à l\'éditeur et à l\'hébergement de ce site.', 'en' => 'Legal information about the publisher and hosting of this site.', 'mg' => 'Fampahalalana ara-dalàna momba ny mpamoaka sy ny fitrandrahana ity tranonkala ity.'],
    'mentions_legales_s1_titre' => ['fr' => '1. Éditeur du site', 'en' => '1. Site publisher', 'mg' => '1. Mpamoaka ny tranonkala'],
    'mentions_legales_s1_texte' => ['fr' => 'Ce site est édité par l\'Institut Supérieur des Sciences et Technologies de Mahajanga (ISSTM), établissement d\'enseignement supérieur basé à Mahajanga, Madagascar.', 'en' => 'This site is published by the Institut Supérieur des Sciences et Technologies de Mahajanga (ISSTM), a higher education institution based in Mahajanga, Madagascar.', 'mg' => 'Namoaka ity tranonkala ity ny Institut Supérieur des Sciences et Technologies de Mahajanga (ISSTM), sekoly ambony misy any Mahajanga, Madagasikara.'],
    'mentions_legales_s2_titre' => ['fr' => '2. Contact', 'en' => '2. Contact', 'mg' => '2. Fifandraisana'],
    'mentions_legales_s2_texte' => ['fr' => 'Email : isstm.univ.umg@gmail.com — Téléphone : +261 38 15 439 77 — Adresse : Mahajanga, Madagascar.', 'en' => 'Email: isstm.univ.umg@gmail.com — Phone: +261 38 15 439 77 — Address: Mahajanga, Madagascar.', 'mg' => 'Mailaka : isstm.univ.umg@gmail.com — Finday : +261 38 15 439 77 — Adiresy : Mahajanga, Madagasikara.'],
    'mentions_legales_s3_titre' => ['fr' => '3. Hébergement', 'en' => '3. Hosting', 'mg' => '3. Fitrandrahana'],
    'mentions_legales_s3_texte' => ['fr' => 'Le site est hébergé sur l\'infrastructure technique mise à disposition par l\'ISSTM.', 'en' => 'The site is hosted on the technical infrastructure provided by ISSTM.', 'mg' => 'Voarindra amin\'ny rafitra ara-teknika omen\'ny ISSTM ny tranonkala.'],
    'mentions_legales_s4_titre' => ['fr' => '4. Propriété intellectuelle', 'en' => '4. Intellectual property', 'mg' => '4. Fananana ara-tsaina'],
    'mentions_legales_s4_texte' => ['fr' => 'L\'ensemble des contenus présents sur ce site (textes, images, logos, mise en page) est la propriété de l\'ISSTM, sauf mention contraire, et ne peut être reproduit sans autorisation préalable.', 'en' => 'All content on this site (text, images, logos, layout) is the property of ISSTM, unless otherwise stated, and may not be reproduced without prior authorization.', 'mg' => 'Fananan\'ny ISSTM ny votoaty rehetra ao amin\'ity tranonkala ity (soratra, sary, logo, fandrindrana), raha tsy voalaza hafa, ary tsy azo adika raha tsy misy fahazoan-dalana mialoha.'],
    'mentions_legales_s5_titre' => ['fr' => '5. Responsabilité', 'en' => '5. Liability', 'mg' => '5. Andraikitra'],
    'mentions_legales_s5_texte' => ['fr' => 'L\'ISSTM s\'efforce d\'assurer l\'exactitude des informations diffusées sur ce site, mais ne saurait être tenu responsable des erreurs, omissions ou de l\'indisponibilité temporaire du service.', 'en' => 'ISSTM strives to ensure the accuracy of the information published on this site, but cannot be held responsible for errors, omissions or temporary unavailability of the service.', 'mg' => 'Miezaka ny hahazoana antoka ny fahamarinan\'ny fampahalalana aparitaka amin\'ity tranonkala ity ny ISSTM, saingy tsy azo tomponandraikitra amin\'ny fahadisoana, fanadinoana na tsy fahatontosan\'ny serivisy vonjimaika.'],

    // --- Footer FAQ ---
    'faq_titre' => ['fr' => 'Questions Fréquentes', 'en' => 'Frequently Asked Questions', 'mg' => 'Fanontaniana Matetika Apetraka'],
    'faq_q1' => ['fr' => 'Comment s\'inscrire à l\'ISSTM ?', 'en' => 'How do I register at ISSTM?', 'mg' => 'Ahoana ny fisoratana anarana ao amin\'ny ISSTM ?'],
    'faq_a1' => ['fr' => 'Remplissez le formulaire d\'inscription disponible sur notre site, puis déposez votre dossier au secrétariat avec les pièces requises.', 'en' => 'Fill out the registration form available on our website, then submit your file to the secretariat with the required documents.', 'mg' => 'Fenoy ny taratasy fisoratana anarana hita eto amin\'ny tranonkalanay, avy eo apetraho any amin\'ny sekretera ny antontan-taratasinao miaraka amin\'ny fepetra takiana.'],
    'faq_q2' => ['fr' => 'Quelles filières propose l\'institut ?', 'en' => 'What programs does the institute offer?', 'mg' => 'Inona ireo sampam-pianarana atolotry ny institiota ?'],
    'faq_a2' => ['fr' => 'L\'ISSTM propose des Licences et Masters en Sciences et Technologies Industrielles, Génie Civil et Sciences du Numérique. Consultez la page Parcours pour plus de détails.', 'en' => 'ISSTM offers Bachelor\'s and Master\'s degrees in Industrial Science and Technology, Civil Engineering, and Digital Science. See the Programs page for more details.', 'mg' => 'Manolotra Licence sy Master momba ny Siansa sy Teknolojia Indostrialy, Injeniera Sivily ary Siansa Nomerika ny ISSTM. Jereo ny pejy Lalana raha te hahafantatra bebe kokoa.'],
    'faq_q3' => ['fr' => 'Comment bénéficier d\'une bourse d\'études ?', 'en' => 'How can I get a scholarship?', 'mg' => 'Ahoana ny fomba hahazoana vatsim-pianarana ?'],
    'faq_a3' => ['fr' => 'Les conditions et démarches pour les bourses sont détaillées sur notre page dédiée à la Bourse.', 'en' => 'The conditions and procedures for scholarships are detailed on our dedicated Scholarship page.', 'mg' => 'Ny fepetra sy ny dingana amin\'ny vatsim-pianarana dia hita amin\'ny pejy Vatsim-pianarana natokana ho azy.'],
    'faq_q4' => ['fr' => 'Comment contacter l\'administration ?', 'en' => 'How can I contact the administration?', 'mg' => 'Ahoana ny fomba fifandraisana amin\'ny fitantanana ?'],
    'faq_a4' => ['fr' => 'Vous pouvez nous écrire à isstm.univ.umg@gmail.com, nous appeler au +261 38 15 439 77 ou nous contacter via notre page Facebook.', 'en' => 'You can email us at isstm.univ.umg@gmail.com, call us at +261 38 15 439 77, or reach us via our Facebook page.', 'mg' => 'Afaka mandefa mailaka any amin\'ny isstm.univ.umg@gmail.com ianao, miantso ny +261 38 15 439 77 na mifandray aminay amin\'ny alalan\'ny pejy Facebook.'],
    'faq_q5' => ['fr' => 'Où se trouve le campus de l\'ISSTM ?', 'en' => 'Where is the ISSTM campus located?', 'mg' => 'Aiza ny tobim-pianaran\'ny ISSTM ?'],
    'faq_a5' => ['fr' => 'Le campus principal se situe à Mahajanga, avec une annexe au bâtiment Ex-Lolo, en face de Leader Price, Majunga be.', 'en' => 'The main campus is located in Mahajanga, with an annex at the Ex-Lolo building, opposite Leader Price, Majunga be.', 'mg' => 'Ny tobim-pianarana lehibe dia any Mahajanga, ary misy sampana any amin\'ny trano Ex-Lolo, tandrifin\'i Leader Price, Majunga be.'],
    'faq_q6' => ['fr' => 'Quelles sont les conditions d\'admission ?', 'en' => 'What are the admission requirements?', 'mg' => 'Inona ireo fepetra takiana hidirana ?'],
    'faq_a6' => ['fr' => 'L\'admission se fait sur dossier et/ou concours selon le niveau et la filière visée. Consultez la page Inscription pour la procédure complète.', 'en' => 'Admission is based on application review and/or entrance exam depending on the level and program. See the Registration page for the full procedure.', 'mg' => 'Ny fidirana dia atao amin\'ny alalan\'ny antontan-taratasy sy/na fizahan-toetra arakaraka ny ambaratonga sy ny sampana tiana. Jereo ny pejy Fisoratana anarana raha te hahafantatra ny dingana feno.'],
    'faq_q7' => ['fr' => 'Comment consulter la liste des enseignants ?', 'en' => 'How can I view the list of teachers?', 'mg' => 'Ahoana ny fomba fijerena ny lisitry ny mpampianatra ?'],
    'faq_a7' => ['fr' => 'La liste complète des enseignants-chercheurs et vacataires est disponible sur notre page Enseignants.', 'en' => 'The complete list of teacher-researchers and part-time lecturers is available on our Teachers page.', 'mg' => 'Ny lisitra feno ny mpampianatra-mpikaroka sy ny mpampianatra an-tselika dia hita ao amin\'ny pejy Mpampianatra.'],
    'faq_q8' => ['fr' => 'Quelles activités sont proposées pour la vie étudiante ?', 'en' => 'What activities are offered for student life?', 'mg' => 'Inona ireo hetsika atolotra ho an\'ny fiainan\'ny mpianatra ?'],
    'faq_a8' => ['fr' => 'Associations, événements culturels et sportifs, clubs académiques : découvrez tout cela sur la page Vie étudiante.', 'en' => 'Associations, cultural and sports events, academic clubs: discover it all on the Student Life page.', 'mg' => 'Fikambanana, hetsika ara-kolontsaina sy fanatanjahan-tena, klioba akademika : hitanao rehetra izany ao amin\'ny pejy Fiainan\'ny mpianatra.'],
    'faq_q9' => ['fr' => 'Dans quelle langue les cours sont-ils dispensés ?', 'en' => 'What language are courses taught in?', 'mg' => 'Amin\'ny teny inona no ampianarana ?'],
    'faq_a9' => ['fr' => 'Les cours sont principalement dispensés en français, avec certains supports et interventions en anglais selon les filières.', 'en' => 'Courses are mainly taught in French, with some materials and sessions in English depending on the program.', 'mg' => 'Amin\'ny teny frantsay indrindra no ampianarana, misy ihany koa fitaovana sy fotoana amin\'ny teny anglisy arakaraka ny sampana.'],
    'faq_q10' => ['fr' => 'Quand débute l\'année académique ?', 'en' => 'When does the academic year start?', 'mg' => 'Rahoviana no manomboka ny taom-pianarana ?'],
    'faq_a10' => ['fr' => 'La rentrée académique a généralement lieu en fin d\'année ou en début d\'année civile ; contactez le secrétariat pour connaître les dates précises.', 'en' => 'The academic year typically starts at the end or the beginning of the calendar year; contact the secretariat for exact dates.', 'mg' => 'Amin\'ny faran\'ny taona na amin\'ny fiandohan\'ny taona kalandrie no matetika manombohan\'ny taom-pianarana ; antsoy ny sekretera raha te hahafantatra ny daty marina.'],

    // --- Page Historique ---
    'histoire_titre' => ['fr' => 'Notre Histoire', 'en' => 'Our History', 'mg' => 'Ny Tantara'],
    'histoire_soustitre' => ['fr' => "Découvrez la genèse et l'évolution de l'ISSTM.", 'en' => 'Discover the genesis and evolution of ISSTM.', 'mg' => 'Fantaro ny niandohany sy ny fivoaran\'ny ISSTM.'],
    'creation_contexte' => ['fr' => 'Création et Contexte', 'en' => 'Creation and Context', 'mg' => 'Fananganana sy ny manodidina'],
    'creation_p1' => ['fr' => "Depuis la création du Centre Universitaire de Mahajanga en 1977, puis l’instauration des six Universités de Madagascar en 1988, l’évolution de l’offre de formation est restée relativement limitée. Toutefois, à partir de l’année universitaire 2010-2011, une diversification notable des formations a été engagée au sein de l’Université de Mahajanga.", 'en' => 'Since the creation of the University Center of Mahajanga in 1977, then the establishment of the six Universities of Madagascar in 1988, the evolution of the training offer has remained relatively limited. However, from the 2010-2011 academic year, a notable diversification of training was initiated within the University of Mahajanga.', 'mg' => 'Hatramin\'ny nananganana ny Foibem-pianarana Oniversitera an\'i Mahajanga tamin\'ny 1977, ary avy eo ny nanorenana ireo Oniversite enina eto Madagasikara tamin\'ny 1988, dia somary voafetra ihany ny fivoaran\'ny tolotra fiofanana. Na izany aza, nanomboka tamin\'ny taom-pianarana 2010-2011, dia nisy fanitarana lehibe teo amin\'ny sehatry ny fiofanana teo anivon\'ny Oniversiten\'i Mahajanga.'],
    'creation_p2' => ['fr' => "C’est dans ce contexte qu’a été créé, au cours de l’année universitaire 2011-2012, l’Institut Supérieur des Sciences et Technologies de Mahajanga (ISSTM). Cet institut figure parmi les nouveaux centres de formation dédiés à la préparation de techniciens supérieurs hautement qualifiés.", 'en' => 'It is in this context that the Higher Institute of Science and Technology of Mahajanga (ISSTM) was created during the 2011-2012 academic year. This institute is one of the new training centers dedicated to the preparation of highly qualified senior technicians.', 'mg' => 'Tao anatin\'izany no nananganana ny Institut Supérieur des Sciences et Technologies de Mahajanga (ISSTM) nandritra ny taom-pianarana 2011-2012. Ity institiota ity dia anisan\'ireo foibem-piofanana vaovao natokana hanomanana teknisiana ambony manana fahaizana avo.'],
    'objectifs_majeurs' => ['fr' => 'Nos Objectifs Majeurs', 'en' => 'Our Major Objectives', 'mg' => 'Ny Tanjonay Lehibe'],
    'objectifs_p1' => ['fr' => "La mise en place de l’ISSTM répond à plusieurs enjeux majeurs, notamment :", 'en' => 'The establishment of ISSTM responds to several major challenges, including:', 'mg' => 'Ny fananganana ny ISSTM dia mamaly fanamby lehibe maromaro, indrindra indrindra :'],
    'objectif_1' => ['fr' => "Les exigences du développement économique régional.", 'en' => 'The requirements of regional economic development.', 'mg' => 'Ny fitakian\'ny fampandrosoana ara-toekarena isam-paritra.'],
    'objectif_2' => ['fr' => "Le manque de cadres techniques intermédiaires au sein des entreprises et des collectivités territoriales décentralisées.", 'en' => 'The lack of intermediate technical managers within companies and decentralized local authorities.', 'mg' => 'Ny tsy fahampian\'ny mpiandraikitra teknika anelanelany eo anivon\'ny orinasa sy ny vondrom-bahoaka itsinjaram-pahefana.'],
    'objectif_3' => ['fr' => "La volonté de réduire les charges financières des familles contraintes d’envoyer leurs enfants poursuivre leurs études en dehors de la province de Mahajanga.", 'en' => 'The desire to reduce the financial burdens of families forced to send their children to study outside the province of Mahajanga.', 'mg' => 'Ny finiavana hampihena ny fandaniana ara-bolan\'ireo fianakaviana voatery mandefa ny zanany hanohy fianarana any ivelan\'ny faritanin\'i Mahajanga.'],
    'statut_pedagogie' => ['fr' => 'Statut et Pédagogie', 'en' => 'Status and Pedagogy', 'mg' => 'Sata sy Fampianarana'],
    'statut_p1' => ['fr' => "À l’issue de leur formation, les diplômés de l’ISSTM sont directement opérationnels dans divers domaines. Par ailleurs, l’ISSTM a acquis le statut d’établissement à part entière, au même titre que l’IOSTM, la Faculté de Médecine et la FSTE, conformément au décret n°2017-418 du 06 juin 2017.", 'en' => 'At the end of their training, ISSTM graduates are directly operational in various fields. In addition, ISSTM has acquired the status of a full-fledged establishment, in the same way as IOSTM, the Faculty of Medicine and the FSTE, in accordance with Decree No. 2017-418 of June 6, 2017.', 'mg' => 'Rehefa vita ny fiofanany, dia afaka miasa avy hatrany amin\'ny sehatra isan-karazany ireo nahazo diplaoma tao amin\'ny ISSTM. Ankoatra izany, ny ISSTM dia nahazo ny satan\'ny sekoly feno, mitovy amin\'ny IOSTM, ny Faculté de Médecine ary ny FSTE, araka ny didim-panjakana laharana faha-2017-418 tamin\'ny 06 jona 2017.'],
    'statut_p2' => ['fr' => "Les formations dispensées, à caractère scientifique et technique, sont renforcées par une immersion dans le milieu professionnel à travers des visites d’imprégnation, des stages en entreprise ainsi que l’intervention de professionnels spécialisés.", 'en' => 'The training provided, of a scientific and technical nature, is reinforced by an immersion in the professional environment through impregnation visits, company internships as well as the intervention of specialized professionals.', 'mg' => 'Ny fiofanana omena, izay manana endrika siantifika sy teknika, dia hamafisina amin\'ny alalan\'ny fampidirana an-tsehatra eo amin\'ny tontolon\'ny asa amin\'ny alalan\'ny fitsidihana, ny fanaovana fampiharana an-trano asa ary ny fandraisan\'anjaran\'ireo matihanina manokana.'],
    'offre_formation' => ['fr' => 'Offre de Formation (LMD)', 'en' => 'Training Offer (LMD)', 'mg' => 'Tolotra Fiofanana (LMD)'],
    'offre_p1' => ['fr' => "Organisée selon le système LMD (Licence-Master-Doctorat), la formation est payante et conduit à l’obtention d’un diplôme de Licence Professionnelle et de Master Recherche dans les mentions suivantes :", 'en' => 'Organized according to the LMD (License-Master-Doctorate) system, the training is fee-paying and leads to a Professional License and Research Master diploma in the following fields:', 'mg' => 'Voalamina araka ny rafitra LMD (Licence-Master-Doctorat), ny fiofanana dia andoavam-bola ary mitondra mankany amin\'ny fahazoana diplaoma Licence Professionnelle sy Master Recherche amin\'ireto sampana manaraka ireto :'],
