    'desc_parcours_gi' => ['fr' => 'Formation en développement logiciel, systèmes d\'information et technologies web.', 'en' => 'Training in software development, information systems, and web technologies.', 'mg' => 'Fiofanana momba ny famolavolana rindrambaiko, rafitra fampahalalana ary teknolojia web.'],
