    'desc_parcours_gei' => ['fr' => 'Formation en électronique embarquée, Internet des Objets (IoT) et systèmes intelligents.', 'en' => 'Training in embedded electronics, Internet of Things (IoT), and intelligent systems.', 'mg' => 'Fiofanana momba ny elektronika anaty, Internet an\'ny Zavatra (IoT) ary rafitra manan-tsaina.'],
    'desc_parcours_ge' => ['fr' => 'Formation en électrotechnique, automatisme, et gestion de l\'énergie électrique.', 'en' => 'Training in electrotechnics, automation, and electrical energy management.', 'mg' => 'Fiofanana momba ny elektroteknika, automatisme ary fitantanana ny angovo elektrika.'],
    'desc_parcours_gind' => ['fr' => 'Formation en management industriel, logistique, qualité et organisation de la production.', 'en' => 'Training in industrial management, logistics, quality, and production organization.', 'mg' => 'Fiofanana momba ny fitantanana indostrialy, lojistika, kalitao ary fandaminana ny famokarana.'],
    'desc_parcours_gt' => ['fr' => 'Formation en énergétique, thermodynamique, et optimisation de l\'efficacité énergétique.', 'en' => 'Training in energetics, thermodynamics, and energy efficiency optimization.', 'mg' => 'Fiofanana momba ny angovo, termodinamika ary fanatsarana ny fahombiazan\'ny angovo.'],
    'desc_parcours_gcivil' => ['fr' => 'Formation en construction, calcul de structures et utilisation des matériaux de construction.', 'en' => 'Training in construction, structural calculation, and use of construction materials.', 'mg' => 'Fiofanana momba ny fanorenana, fikajiana rafitra ary fampiasana fitaovam-panorenana.'],
    'desc_parcours_ghyd' => ['fr' => 'Formation en gestion des ressources en eau, hydraulique urbaine et aménagements.', 'en' => 'Training in water resource management, urban hydraulics, and developments.', 'mg' => 'Fiofanana momba ny fitantanana ny rano, ny rano an-tanàn-dehibe ary ny fanajariana.'],
    'desc_parcours_garchi' => ['fr' => 'Formation en conception architecturale, urbanisme, et design d\'espace durable.', 'en' => 'Training in architectural design, urban planning, and sustainable space design.', 'mg' => 'Fiofanana momba ny famolavolana maritrano, fandrindrana ny tanàna ary famolavolana habaka maharitra.'],
    'desc_conseil_etablissement' => ['fr' => "Définit la stratégie globale et veille au bon fonctionnement de l'institut.", 'en' => 'Defines the overall strategy and ensures the proper functioning of the institute.', 'mg' => 'Mamaritra ny paikady ankapobeny ary miantoka ny fampandehanan-draharaha ao amin\'ny institiota.'],
    'desc_directeur' => ['fr' => "Assure la direction générale, la mise en œuvre de la stratégie et représente l'institut.", 'en' => 'Ensures general management, strategy implementation, and represents the institute.', 'mg' => 'Miantoka ny fitantanana ankapobeny, ny fampiharana ny paikady ary misolo tena ny institiota.'],
    'desc_prmp' => ['fr' => 'Pilote les projets de recherche et de modernisation pour une pédagogie innovante.', 'en' => 'Leads research and modernization projects for innovative pedagogy.', 'mg' => 'Mitarika ny tetikasa fikarohana sy fanavaozana ho an\'ny fampianarana manara-penitra.'],
    'desc_conseil_scientifique' => ['fr' => 'Organe consultatif garant de la politique scientifique et de la qualité de la recherche.', 'en' => 'Advisory body guaranteeing scientific policy and research quality.', 'mg' => 'Taova mpanolo-tsaina miantoka ny politika siantifika sy ny kalitaon\'ny fikarohana.'],
    'desc_college_enseignants' => ['fr' => 'Représente le corps professoral et participe aux décisions académiques.', 'en' => 'Represents the faculty and participates in academic decisions.', 'mg' => 'Misolo tena ny mpampianatra ary mandray anjara amin\'ny fanapahan-kevitra akademika.'],
    'desc_secretariat_direction' => ['fr' => 'Assure le support administratif direct du Directeur et la gestion des dossiers.', 'en' => 'Provides direct administrative support to the Director and manages files.', 'mg' => 'Miantoka ny fanohanana ara-pitantanana mivantana ny Tale sy ny fitantanana ny antontan-taratasy.'],
    'desc_resp_qualite' => ['fr' => "Met en œuvre et supervise la démarche d'assurance qualité pour l'excellence académique.", 'en' => 'Implements and supervises the quality assurance process for academic excellence.', 'mg' => 'Mampihatra sy manara-maso ny dingan\'ny fiantohana ny kalitao ho an\'ny fahatsarana akademika.'],
    'desc_resp_comm' => ['fr' => "Gère l'image et la communication interne et externe de l'établissement.", 'en' => 'Manages the image and internal and external communication of the establishment.', 'mg' => 'Mitantana ny endrika sy ny serasera anatiny sy ivelan\'ny sekoly.'],
    'desc_coordo_pedagogique' => ['fr' => 'Supervise l\'ensemble des formations, garantit la cohérence et la qualité des programmes.', 'en' => 'Supervises all training courses, guarantees the consistency and quality of the programs.', 'mg' => 'Manara-maso ny fiofanana rehetra, miantoka ny firindrana sy ny kalitaon\'ny fandaharam-pianarana.'],
    'desc_mention_stnpa' => ['fr' => "Spécialise dans les technologies du numérique, de l'audiovisuel et de l'informatique.", 'en' => 'Specializes in digital, audiovisual, and computer technologies.', 'mg' => 'Manampahaizana manokana amin\'ny teknolojia nomerika, haino aman-jery ary informatika.'],
    'desc_mention_sti' => ['fr' => "Prépare aux métiers de l'ingénierie industrielle, de l'énergie et de la production.", 'en' => 'Prepares for careers in industrial engineering, energy, and production.', 'mg' => 'Manomana ho amin\'ny asan\'ny injeniera indostrialy, angovo ary famokarana.'],
    'desc_mention_gc' => ['fr' => 'Forme des experts en construction, hydraulique et aménagement durable.', 'en' => 'Trains experts in construction, hydraulics, and sustainable development.', 'mg' => 'Mamolavola manam-pahaizana momba ny fanorenana, ny rano ary ny fampandrosoana maharitra.'],
    'desc_service_cooperation' => ['fr' => 'Développe les partenariats nationaux et internationaux pour enrichir les parcours.', 'en' => 'Develops national and international partnerships to enrich the programs.', 'mg' => 'Mampivelatra ny fiaraha-miasa eo amin\'ny firenena sy iraisam-pirenena mba hanatsarana ny lalam-piofanana.'],
    'desc_secretaire_principal' => ['fr' => "Dirige et coordonne l'ensemble des services administratifs et techniques de l'institut.", 'en' => 'Directs and coordinates all the administrative and technical services of the institute.', 'mg' => 'Mitarika sy mandrindra ny sampan-draharaha ara-pitantanana sy teknika rehetra ao amin\'ny institiota.'],
    'desc_service_compta' => ['fr' => 'Gère la santé financière, le budget et les opérations comptables de l\'établissement.', 'en' => 'Manages the financial health, budget, and accounting operations of the establishment.', 'mg' => 'Mitantana ny fahasalamana ara-bola, ny teti-bola ary ny asa kaonty ao amin\'ny sekoly.'],
    'desc_service_numerique' => ['fr' => "Pilote l'infrastructure informatique, les applications et le support technique aux utilisateurs.", 'en' => 'Manages the IT infrastructure, applications, and technical support for users.', 'mg' => 'Mitarika ny fotodrafitrasa informatika, ny fampiharana ary ny fanohanana teknika ho an\'ny mpampiasa.'],
    'desc_service_scolarite' => ['fr' => "Gère le parcours de l'étudiant, de l'inscription à la diplomation.", 'en' => 'Manages the student\'s journey, from registration to graduation.', 'mg' => 'Mitantana ny dian\'ny mpianatra, manomboka amin\'ny fisoratana anarana ka hatramin\'ny fahazoana diplaoma.'],
    'desc_service_logistique' => ['fr' => 'Assure la gestion des biens, la maintenance des locaux et le support matériel.', 'en' => 'Ensures property management, building maintenance, and material support.', 'mg' => 'Miantoka ny fitantanana ny fananana, ny fikojakojana ny trano ary ny fanohanana ara-pitaovana.'],
    'desc_service_stats' => ['fr' => 'Collecte, analyse et diffuse les données statistiques pour le pilotage de l\'institut.', 'en' => 'Collects, analyzes, and disseminates statistical data for the management of the institute.', 'mg' => 'Manangona, mamakafaka ary manaparitaka ny angona statistika ho an\'ny fitantanana ny institiota.'],
