$translations['admin_securite_titre'] = ['fr' => 'Sécurité des mots de passe', 'en' => 'Password security', 'mg' => 'Fiarovana ny tenimiafina'];
$translations['admin_securite_soustitre'] = ['fr' => 'Activité du circuit "mot de passe oublié" du login', 'en' => 'Activity of the login "forgot password" flow', 'mg' => 'Hetsika amin\'ny lalana "hadino ny tenimiafina"'];
$translations['admin_securite_intro'] = ['fr' => 'Circuit "mot de passe oublié" : l\'utilisateur saisit son email -> le compte est vérifié -> un jeton aléatoire est généré et enregistré avec une expiration (1 heure) -> un email contenant le lien est envoyé. En cliquant sur ce lien, le jeton et son expiration sont vérifiés, l\'utilisateur choisit un nouveau mot de passe (3 critères : 8 caractères minimum, majuscule + minuscule, un chiffre), password_hash() l\'enregistre, puis le jeton est supprimé. Un email de confirmation part une fois le mot de passe réellement changé.', 'en' => '"Forgot password" flow: the user enters their email -> the account is verified -> a random token is generated and saved with an expiration (1 hour) -> an email with the link is sent. Clicking the link verifies the token and its expiration, the user picks a new password (3 criteria: minimum 8 characters, uppercase + lowercase, one digit), password_hash() stores it, then the token is deleted. A confirmation email is sent once the password is actually changed.', 'mg' => 'Lalana "hadino ny tenimiafina" : mampiditra ny mailakany ny mpampiasa -> voamarina ny kaonty -> mamorona sy mitahiry jeton kisendrasendra miaraka amin\'ny daty lany fotoana (ora 1) -> mandefa mailaka misy ny rohy. Rehefa tsindriana ilay rohy dia voamarina ny jeton sy ny daty lany fotoana, misafidy tenimiafina vaovao ny mpampiasa (fepetra 3 : litera 8 farafahakeliny, litera lehibe + kely, isa iray), mitahiry azy io ny password_hash(), avy eo fafana ny jeton. Misy mailaka fanamafisana alefa rehefa tena voavaozina ny tenimiafina.'];
